  name = file.name
  rept = re.compile("\d+[xX]\d+")
  for i in name.split('_'):
    ans = re.findall(rept, i)
    if ans:
      size = ans[0].lower().split('x')
      return int(size[0]), int(size[1])
  return -1, -1


