def dumps(self, reqs, project: RootDependency, content=None) -> str:
    doc = document()
    deps = []
    for req in reqs:
        deps.append(self._format_req(req=req))
    doc['build-system']['requires'] = deps
    return dumps(doc)

def _format_req(self, req):
    line = req.raw_name
    if req.extras:
        line += '[{extras}]'.format(extras=','.join(req.extras))
    line += req.version
    if req.markers:
        line += '; ' + req.markers
    return line

