def find_max(list):
    # base condition
    if len(list) == 1:
        return list[0] 
    else:
        # compare the current element to the next element
        max_element = max(list[0], list[1])
        # remove the compared element
        list.pop(1)
        # call the function on the remaining list
        return find_max(list[:1] + [max_element] + list[1:])

class PrimeNumber
{
    public static void Main()
    {
        Console.Write("Enter a number: ");
        int n = int.Parse(Console.ReadLine());

        for (int i = 2; i <= n; i++)
        {
            if (CheckPrime(i))
            {
                Console.Write(i + " ");
            }
        }
        Console.WriteLine();
    }

    public static bool CheckPrime(int numberToCheck)
    {
        int boundary = (int)Math.Floor(Math.Sqrt(numberToCheck));

        if (numberToCheck == 1) return false;
        if (numberToCheck == 2) return true;

        for (int i = 2; i <= boundary; ++i)
        {
            if (numberToCheck % i == 0) return false;
        }

        return true;
    }
}

